def _coordinates(x, maps):
    (offset, gain, operator) = maps
    return _affine((x - offset) / gain) @ operator

def _trajectory(c, query, traj, times, intercept=True):
    from scipy.optimize import least_squares
    (design, new_design) = (_affine(c), _affine(query)) if intercept else (c, query)
    beta = np.linalg.lstsq(design, traj, rcond=None)[0]
    fitted = design @ beta
    scale = max(float(np.max(np.abs(times))), np.finfo(float).tiny)
    t = times / scale

    def basis(log_rates):
        return -np.expm1(-np.exp(log_rates[:, None]) * t)

    def residual(log_rates):
        modes = basis(log_rates)
        return (fitted @ np.linalg.pinv(modes) @ modes - fitted).ravel()
    log_rates = least_squares(residual, np.log([0.6, 2.7]), bounds=(np.log([0.03, 0.25]), np.log([4.0, 20.0])), max_nfev=100).x
    modes = basis(log_rates)
    return new_design @ (beta @ np.linalg.pinv(modes)) @ modes

def _scalar(a, b, y):
    from scipy.optimize import least_squares
    n = len(y)
    scale = np.maximum(b[:n].std(axis=0), 1e-08)
    b = b / scale
    ab = a[:n]
    rng = np.random.default_rng(1)
    starts = np.r_[np.zeros((1, 4)), np.eye(4), rng.normal(0, 0.5, (8, 4))]
    predictions = []
    for link in (np.sin, np.tanh):

        def design(p, q, base):
            return np.column_stack((base, link(p[0] + q @ p[1:])))

        def residual(p):
            d = design(p, b[:n], ab)
            return np.r_[d @ _ls(d, y) - y, 0.008 * p]
        options = [least_squares(residual, np.r_[0.1, start], max_nfev=120) for start in starts]
        fit = min(options, key=lambda opt: opt.cost)
        d = design(fit.x, b, a)
        predictions.append(d[n:] @ _ls(d[:n], y))
    return np.mean(predictions, axis=0)
